{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "overview_text",
        "itinerary_image",
        "itinerary_heading_stack",
        "itinerary_table",
        "metrics_section_heading",
        "metrics_stack",
        "actions_section_heading",
        "actions_stack",
        "sources_section_heading",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Innovate Tokyo 2025: Conference Overview",
        "variant": "h1"
      },
      "children": []
    },
    "overview_text": {
      "type": "Text",
      "props": {
        "text": "This structured itinerary covers the three-day Innovate Tokyo summit, featuring keynotes on AI ethics, cloud infrastructure, and fintech trends across multiple high-tech venues."
      },
      "children": []
    },
    "itinerary_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Skyscrapers_of_Shinjuku_2009_January.jpg/1200px-Skyscrapers_of_Shinjuku_2009_January.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "itinerary_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "itinerary_section_heading",
        "itinerary_icon"
      ]
    },
    "itinerary_section_heading": {
      "type": "Text",
      "props": {
        "text": "Innovate Tokyo 2025 Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/map.svg"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "activity",
        "highlightColumns": [
          "time",
          "location"
        ],
        "columns": [
          {
            "key": "dayDate",
            "label": "Date"
          },
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          },
          {
            "key": "location",
            "label": "Location"
          }
        ],
        "rows": [
          {
            "dayDate": "October 20, 2025",
            "time": "09:00 - 10:30",
            "activity": "Opening Keynote",
            "location": "Main Hall"
          },
          {
            "dayDate": "October 20, 2025",
            "time": "11:00 - 12:30",
            "activity": "AI Ethics Panel",
            "location": "Room B"
          },
          {
            "dayDate": "October 20, 2025",
            "time": "12:30 - 14:00",
            "activity": "Mandatory Lunch Break",
            "location": "Dining Hall"
          },
          {
            "dayDate": "October 20, 2025",
            "time": "14:00 - 16:00",
            "activity": "Workshop: Sustainable Tech",
            "location": "Lab 1"
          },
          {
            "dayDate": "October 21, 2025",
            "time": "10:00 - 11:30",
            "activity": "Future of Cloud",
            "location": "Room A"
          },
          {
            "dayDate": "October 21, 2025",
            "time": "13:00 - 14:30",
            "activity": "Networking Lunch",
            "location": "Garden"
          },
          {
            "dayDate": "October 21, 2025",
            "time": "15:00 - 17:00",
            "activity": "Cybersecurity Deep Dive",
            "location": "Room C"
          },
          {
            "dayDate": "October 22, 2025",
            "time": "09:30 - 11:00",
            "activity": "Fintech Trends",
            "location": "Room B"
          },
          {
            "dayDate": "October 22, 2025",
            "time": "11:30 - 13:00",
            "activity": "Investor Pitch Session",
            "location": "Executive Suite"
          },
          {
            "dayDate": "October 22, 2025",
            "time": "13:00 - 14:00",
            "activity": "Mandatory Lunch Break",
            "location": "Dining Hall"
          },
          {
            "dayDate": "October 22, 2025",
            "time": "14:00 - 15:30",
            "activity": "Closing Ceremony",
            "location": "Main Hall"
          }
        ]
      },
      "children": []
    },
    "metrics_section_heading": {
      "type": "Text",
      "props": {
        "text": "Engagement Metrics & Logistics",
        "variant": "h2"
      },
      "children": []
    },
    "metrics_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "duration_text",
        "room_util_text",
        "conflict_note_text"
      ]
    },
    "duration_text": {
      "type": "Text",
      "props": {
        "text": "Scheduled Durations: Day 1 (5.0 hours), Day 2 (3.5 hours), Day 3 (4.5 hours)."
      },
      "children": []
    },
    "room_util_text": {
      "type": "Text",
      "props": {
        "text": "Room Utilization: Room B and the Main Hall are the most frequently used venues, each hosting 2 sessions."
      },
      "children": []
    },
    "conflict_note_text": {
      "type": "Text",
      "props": {
        "text": "Conflict Note: On Day 1, the AI Ethics Panel (ends 12:30) and Robotics Workshop (starts 10:30) overlap. To see the full AI talk, prioritize Room B and skip the workshop."
      },
      "children": []
    },
    "actions_section_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "download_app_button",
        "venue_map_button"
      ]
    },
    "download_app_button": {
      "type": "Button",
      "props": {
        "label": "Download App"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://innovatetokyo.jp/app"
          }
        }
      },
      "children": []
    },
    "venue_map_button": {
      "type": "Button",
      "props": {
        "label": "Venue Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://innovatetokyo.jp/venue"
          }
        }
      },
      "children": []
    },
    "sources_section_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "conference_program_button",
        "tokyo_convention_button"
      ]
    },
    "conference_program_button": {
      "type": "Button",
      "props": {
        "label": "Conference Program"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://innovatetokyo.jp/2025/sessions"
          }
        }
      },
      "children": []
    },
    "tokyo_convention_button": {
      "type": "Button",
      "props": {
        "label": "Tokyo Convention Center"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bigsight.jp/english/"
          }
        }
      },
      "children": []
    }
  }
}
